<?php if(!Launch::ready()):?><div class="card">Run cron/migrate-launch.php to install blog storage.</div><?php else:$post=row('SELECT * FROM zentro_posts WHERE id=?',[(int)($_GET['edit']??0)])??[];?><div class="card"><h2><?=empty($post)?'Write an article':'Edit article'?></h2><p>Use short paragraphs. Start a line with ## for a section heading. Content is safely rendered as text.</p><form data-api="admin/blog-save" enctype="multipart/form-data"><input type="hidden" name="id" value="<?=e($post['id']??0)?>"><div class="form-grid"><?php field('title','Article title','text',$post['title']??'');field('slug','URL slug','text',$post['slug']??'');select_field('status','Visibility',['draft'=>'Draft','published'=>'Published'],$post['status']??'draft');?></div><label>Search description<textarea name="description" maxlength="320" required><?=e($post['description']??'')?></textarea></label><label>Article content<textarea name="content" rows="18" maxlength="60000" required><?=e($post['content']??'')?></textarea></label><div class="form-grid"><label>Cover image (JPG, PNG, WebP; up to 4 MB)<input type="file" name="image" accept="image/jpeg,image/png,image/webp"></label><?php field('image_alt','Image description','text',$post['image_alt']??'',false);?></div><?php if(!empty($post['image'])):?><img class="blog-cover" src="<?=url($post['image'])?>" alt="<?=e($post['image_alt'])?>"><?php endif;?><button class="button">Save article</button> <a href="<?=url('/admin/blog')?>">New article</a></form></div><div class="card stack"><h2>Articles</h2><?php foreach(rows('SELECT id,title,status,slug FROM zentro_posts ORDER BY id DESC LIMIT 200') as $p):?><p><a href="<?=url('/admin/blog?edit='.$p['id'])?>"><?=e($p['title'])?></a> <span class="badge"><?=e($p['status'])?></span><?php if($p['status']==='published'):?> <a href="<?=url('/blog/'.$p['slug'])?>">View article</a><?php endif;?></p><?php endforeach;?></div><?php endif;?>
